  novita: [
    { titolo: "L. 182/2025 – annullamento d'ufficio in 6 mesi", testo: "La legge annuale di semplificazione 2025 ha sostituito «dodici mesi» con «sei mesi» nei cc. 1 e 2-bis dell'art. 21-nonies L. 241/1990, dal 18 dicembre 2025. Il termine riguarda i provvedimenti di autorizzazione o di attribuzione di vantaggi economici, compresi quelli formati per silenzio assenso. Correzione rispetto alla versione precedente del corso, che indicava 12 mesi.", stato: "verificato", fonte: "L. 2 dicembre 2025, n. 182, art. 1 (G.U. n. 281 del 3/12/2025)" },
    { titolo: "D.L. 19/2026 (PNRR 2026) conv. L. 50/2026 – conferenza di servizi, SCIA, silenzio assenso", testo: "Il decreto, convertito dalla L. 20 aprile 2026, n. 50, ha ridotto i termini della conferenza di servizi semplificata e simultanea (artt. 14-bis e 14-ter), ritoccato l'art. 19, c. 4 (SCIA) e l'art. 20, cc. 1 e 2-bis (silenzio assenso e relativa attestazione). I valori esatti dei nuovi termini vanno letti sul testo coordinato.", stato: "da verificare", fonte: "D.L. 19 febbraio 2026, n. 19; L. 20 aprile 2026, n. 50 (G.U. n. 91 del 20/4/2026)" },
    { titolo: "Soglie europee 2026–2027", testo: "Dal 1° gennaio 2026: lavori e concessioni 5.404.000 €; servizi e forniture 140.000 € (autorità centrali) e 216.000 € (enti sub-centrali); settori speciali 432.000 € per servizi e forniture. Le soglie dell'affidamento diretto (art. 50: 150.000 € lavori, 140.000 € servizi e forniture) non sono cambiate.", stato: "verificato", fonte: "Reg. delegati UE 2025/2150, 2025/2151, 2025/2152 (GUUE 23/10/2025)" },
    { titolo: "Correttivo D.Lgs. 209/2024 al codice dei contratti", testo: "In vigore dal 31 dicembre 2024; interviene su revisione prezzi, tutele dei lavoratori, digitalizzazione, qualificazione, equo compenso. Non modifica le soglie dell'art. 50 (abrogato solo il c. 3).", stato: "verificato", fonte: "D.Lgs. 31 dicembre 2024, n. 209 (G.U. 31/12/2024)" },
    { titolo: "Bodycam per le forze di polizia (D.L. 48/2025)", testo: "Il decreto sicurezza (conv. L. 80/2025) prevede la dotazione di dispositivi di videosorveglianza indossabili per le forze di polizia impiegate in servizi di ordine pubblico e controllo del territorio. L'estensione e le modalità per la polizia locale restano affidate ai regolamenti e disciplinari comunali, sotto il controllo del Garante.", stato: "da verificare", fonte: "D.L. 11 aprile 2025, n. 48, art. 21; L. 9 giugno 2025, n. 80" },
    { titolo: "eIDAS 2 e portafoglio digitale", testo: "Il Reg. UE 2024/1183 aggiorna eIDAS e introduce il portafoglio europeo di identità digitale; in Italia il sistema IT-Wallet (D.L. 19/2024) è integrato nell'app IO.", stato: "verificato", fonte: "Reg. UE 2024/1183; art. 64-quater CAD" }
  ],

  flash: [
    ["Termine generale di conclusione del procedimento?", "30 giorni, se legge o regolamento non dispongono diversamente (art. 2, c. 2, L. 241/1990)."],
    ["Che cosa deve indicare la motivazione?", "I presupposti di fatto e le ragioni giuridiche, in relazione alle risultanze dell'istruttoria (art. 3 L. 241/1990)."],
    ["Preavviso di rigetto: termine ed effetto?", "10 giorni per le osservazioni; sospende i termini del procedimento (art. 10-bis L. 241/1990)."],
    ["Entro quanto la PA può vietare la prosecuzione di un'attività avviata con SCIA?", "60 giorni (30 in edilizia); dopo, solo alle condizioni dell'art. 21-nonies (art. 19 L. 241/1990)."],
    ["Termine massimo per annullare d'ufficio un'autorizzazione?", "6 mesi dall'adozione, dopo la L. 182/2025 (art. 21-nonies L. 241/1990)."],
    ["Differenza tra revoca e annullamento d'ufficio?", "La revoca colpisce atti legittimi per motivi di opportunità, ex nunc, con indennizzo (art. 21-quinquies); l'annullamento atti illegittimi, ex tunc (art. 21-nonies)."],
    ["Silenzio su una richiesta di accesso documentale?", "Dopo 30 giorni vale rigetto; ricorso al TAR o al difensore civico entro 30 giorni (art. 25 L. 241/1990; art. 116 c.p.a.)."],
    ["Chi può presentare accesso civico generalizzato?", "Chiunque, senza motivazione, nei limiti dell'art. 5-bis (art. 5, c. 2, D.Lgs. 33/2013)."],
    ["Dichiarazione sostitutiva di certificazione e di atto di notorietà?", "Art. 46 (stati e qualità elencati) e art. 47 (stati, qualità e fatti a diretta conoscenza) D.P.R. 445/2000."],
    ["Conseguenze di una dichiarazione sostitutiva falsa?", "Decadenza dai benefici e divieto di agevolazioni per 2 anni (art. 75); reato, di regola art. 483 c.p. (art. 76 D.P.R. 445/2000)."],
    ["Valore della PEC?", "Equivale alla notificazione per mezzo della posta, salvo diversa previsione (art. 48 CAD)."],
    ["Quale norma regola la privacy nelle attività di polizia giudiziaria?", "D.Lgs. 51/2018 (dir. UE 2016/680); per l'attività amministrativa vale il GDPR."],
    ["Per quanto si conservano le immagini della videosorveglianza comunale?", "Fino a 7 giorni, salvo speciali esigenze (art. 6, c. 8, D.L. 11/2009)."],
    ["Soglie dell'affidamento diretto?", "Lavori < 150.000 €; servizi e forniture < 140.000 € (art. 50 D.Lgs. 36/2023)."],
    ["Cosa significa RUP nel D.Lgs. 36/2023?", "Responsabile unico del progetto (art. 15)."]
  ],

